.app-frame {
  min-height: 100vh;
  background: var(--bg-main);
}

.app-main {
  grid-template-rows: var(--context-bar-height) minmax(0, 1fr);
}

.menu-rail {
  padding: var(--space-2) 0;
  gap: var(--space-2);
  background: var(--surface-raised);
  border-right-color: var(--line);
  box-shadow: none;
}

.menu-rail-toggle,
.menu-item {
  border: 0;
  border-radius: 0;
}

.menu-rail-toggle {
  height: var(--context-bar-height);
  min-height: var(--context-bar-height);
  background: transparent;
  padding: 0 18px;
}

.menu-item {
  min-height: 48px;
  padding: 0 18px;
}

.menu-rail-nav {
  gap: 0;
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.menu-group {
  display: grid;
  align-content: start;
}

.menu-group-center {
  align-self: center;
