  title?: string;
  icon?: IconName;
  updatedLabel: string;
  socketState: string;
  totalStreams?: number;
  liveLabel: string;
  liveTone: "success" | "warning";
  onToggleLive: () => void;
  onToggleTheme: () => void;
  theme: "light" | "dark";
  compact?: boolean;
};

export function AppContextBar({
  title = "Media Stream Monitor",
  icon,
  updatedLabel,
  socketState,
  totalStreams,
  liveLabel,
  liveTone,
  onToggleLive,
  onToggleTheme,
  theme,
  compact = false
}: AppContextBarProps) {
