import { StatusBadge } from "./StatusBadge";
import { Icon, type IconName } from "./Icon";

type AppContextBarProps = {
  title?: string;
  icon?: IconName;
  updatedLabel: string;
  socketState: string;
  totalStreams?: number;
  liveLabel: string;
  liveTone: "success" | "warning";
  onToggleLive: () => void;
  onToggleTheme: () => void;
  theme: "light" | "dark";
  compact?: boolean;
};

export function AppContextBar({
  title = "Media Stream Monitor",
  icon,
  updatedLabel,
  socketState,
  totalStreams,
  liveLabel,
  liveTone,
  onToggleLive,
  onToggleTheme,
  theme,
  compact = false
}: AppContextBarProps) {
  return (
    <header className={`app-context-bar ${compact ? "app-context-bar-compact" : ""}`}>
      <div className="app-context-identity">
        {icon && <Icon className="app-context-icon" name={icon} size={14} />}
        <strong>{title}</strong>
        <span>{updatedLabel}</span>
      </div>
      <div className="app-context-status" aria-label="Application status">
        {totalStreams !== undefined && <StatusBadge>{totalStreams} streams</StatusBadge>}
        <StatusBadge>{socketState}</StatusBadge>
        <button type="button" className={`context-live-toggle is-${liveTone}`} onClick={onToggleLive} title="Toggle live updates">
          <span aria-hidden="true" />
          {liveLabel}
        </button>
        <button
          type="button"
          className="context-theme-toggle icon-only"
          onClick={onToggleTheme}
          title={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
          aria-label={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
        >
          <Icon name={theme === "light" ? "themeDark" : "themeLight"} size={16} />
        </button>
      </div>
    </header>
  );
}
