  topologyStaleRetentionSec: Number(argv.topologyStaleRetentionSec ?? process.env.TOPOLOGY_STALE_RETENTION_SEC ?? 600),
  topologyMaxStaleEdges: Number(argv.topologyMaxStaleEdges ?? process.env.TOPOLOGY_MAX_STALE_EDGES ?? 2000),
  stmConfigFile,
  externalPagesDir,
  historyWindowSec: Number(process.env.HISTORY_WINDOW_SEC ?? 300),
  timelineWindowSec: Number(process.env.TIMELINE_WINDOW_SEC ?? 3600),
