  value?: number;
  avg?: number;
  min?: number;
  max?: number;
  count?: number;
};

export type MetricPoint = NumericStat & {
  time: number;
};

export type TimelineSegment = {
  start: number;
  end: number | null;
};

export type TimelineWindow = {
  from: number;
  to: number;
};
export type TimelineDataGap = {
  from: number;
  to: number;
  reason: "monitor-unavailable";
};

export type LiveStatus = {
  observedAt: number | null;
};


export type ScopeLayer =
  | { kind: "vlan"; id?: string; priority?: string; dei?: string }
  | { kind: "vxlan"; vni?: string };

export type NetworkScope = {
  interfaceId?: number;
  interfaceName?: string;
  known: boolean;
  layers: ScopeLayer[];
};

export type TimelineRow = {
  rowType: "stream" | "flow";
