};

export type StreamState = Omit<StreamListItem, "flows"> & {
import type { AppConfig, MaintenanceSettingsResponse, ProtocolMapDocument, ProtocolMapResponse, AlertsDocument, AlertsResponse, BootstrapResponse, EventLogItem, InterfaceListItem, InterfaceMetricsResponse, StreamListItem, StreamMetricsResponse, StreamState, Summary, TimelineViewResponse, DashboardLayout, StreamsSnapshotResponse, TopologySnapshot, LiveStatus } from "../types/api";

export type MetricsRangeQuery = {
  windowSec?: number;
  from?: number;
  to?: number;
  resolutionSec?: number;
};

export type TimelineRangeQuery = {
  from?: number;
  to?: number;
  includeFlows?: boolean;
};

export async function getDashboardLayouts(): Promise<DashboardLayout[]> {
  return getJson("/api/dashboard-layouts");
}

export async function saveDashboardLayouts(layouts: DashboardLayout[]): Promise<DashboardLayout[]> {
  const response = await fetch("/api/dashboard-layouts", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(layouts)
  });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<DashboardLayout[]>;
}

export async function getStreams(): Promise<StreamListItem[]> {
  return getJson("/api/streams");
}

export async function getStreamsSnapshotAt(timeSec: number): Promise<StreamsSnapshotResponse> {
  return getJson(`/api/streams?time=${encodeURIComponent(String(timeSec))}`);
}

export async function getAppConfig(): Promise<AppConfig> {
  return getJson("/api/config");
}


export async function getLiveStatus(): Promise<LiveStatus> {
  return getJson("/api/live");
}
export async function getMaintenanceSettings(): Promise<MaintenanceSettingsResponse> {
  return getJson("/api/maintenance/frontend-settings");
}

export async function saveMaintenanceSettings(revision: number, values: AppConfig): Promise<MaintenanceSettingsResponse> {
  const response = await fetch("/api/maintenance/frontend-settings", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ revision, values })
  });
  if (!response.ok) {
    const body = await response.json().catch(() => undefined) as { error?: string } | undefined;
    throw new Error(body?.error ?? "Request failed");
  }
  return response.json() as Promise<MaintenanceSettingsResponse>;
}

export async function getAlertsSettings(): Promise<AlertsResponse> {
  const response = await fetch("/api/maintenance/alerts");
  if (!response.ok) { const body = await response.json().catch(() => undefined) as { error?: string } | undefined; throw new Error(body?.error ?? response.status + " " + response.statusText); }
  return response.json() as Promise<AlertsResponse>;
}

export async function saveAlertsSettings(revision: string, document: AlertsDocument): Promise<AlertsResponse> {
  const response = await fetch("/api/maintenance/alerts", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revision, document }) });
  if (!response.ok) { const body = await response.json().catch(() => undefined) as { error?: string } | undefined; throw new Error(body?.error ?? "Request failed"); }
  return response.json() as Promise<AlertsResponse>;
}

export async function getProtocolMapSettings(): Promise<ProtocolMapResponse> {
  const response = await fetch("/api/maintenance/protocol-map");
  if (!response.ok) {
    const body = await response.json().catch(() => undefined) as { error?: string } | undefined;
    throw new Error(body?.error ?? response.status + " " + response.statusText);
  }
  return response.json() as Promise<ProtocolMapResponse>;
}

export async function saveProtocolMapSettings(revision: string, path: string, document: ProtocolMapDocument): Promise<ProtocolMapResponse> {
  const response = await fetch("/api/maintenance/protocol-map", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revision, path, document }) });
  if (!response.ok) { const body = await response.json().catch(() => undefined) as { error?: string } | undefined; throw new Error(body?.error ?? "Request failed"); }
  return response.json() as Promise<ProtocolMapResponse>;
}

export async function getBootstrap(): Promise<BootstrapResponse> {
  return getJson("/api/bootstrap");
}

export async function getTopology(timeSec?: number): Promise<TopologySnapshot> {
  const suffix = timeSec !== undefined ? `?time=${encodeURIComponent(String(timeSec))}` : "";
  return getJson(`/api/topology${suffix}`);
}

export async function getTimeline(query: TimelineRangeQuery = {}): Promise<TimelineViewResponse> {
  const params = new URLSearchParams();
  if (query.from !== undefined) params.set("from", String(query.from));
  if (query.to !== undefined) params.set("to", String(query.to));
  if (query.includeFlows !== undefined) params.set("includeFlows", query.includeFlows ? "1" : "0");
  const suffix = params.toString() ? `?${params.toString()}` : "";
  return getJson(`/api/timeline${suffix}`);
}

export async function getInterfaces(): Promise<InterfaceListItem[]> {
  return getJson("/api/interfaces");
}

export async function getInterfaceMetrics(interfaceId: number, windowSec = 300): Promise<InterfaceMetricsResponse> {
  return getJson(`/api/interfaces/${interfaceId}/metrics?windowSec=${windowSec}`);
}

export async function getInterfaceMetricsByKey(key: string, query: number | MetricsRangeQuery = 300): Promise<InterfaceMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") params.set("windowSec", String(query));
  else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
  }
  return getJson(`/api/interfaces/by-key/${encodeURIComponent(key)}/metrics?${params.toString()}`);
}

export async function getSummary(): Promise<Summary> {
  return getJson("/api/summary");
}

export async function getStream(streamKey: string): Promise<StreamState> {
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}`);
}

export async function getStreamMetrics(streamKey: string, query: number | MetricsRangeQuery = 300): Promise<StreamMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") {
    params.set("windowSec", String(query));
  } else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
    if (query.resolutionSec !== undefined) params.set("resolutionSec", String(query.resolutionSec));
  }
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}/metrics?${params.toString()}`);
}

export async function getEvents(params: {
  streamKey?: string;
  flowKey?: string;
  interfaceId?: number;
  limit?: number;
  from?: number;
  to?: number;
  proto?: string;
  level?: "info" | "warn" | "error";
  type?: string;
} = {}): Promise<EventLogItem[]> {
  const query = new URLSearchParams();
  if (params.streamKey) query.set("streamKey", params.streamKey);
  if (params.flowKey) query.set("flowKey", params.flowKey);
  if (params.interfaceId !== undefined) query.set("interfaceId", String(params.interfaceId));
  if (params.from !== undefined) query.set("from", String(params.from));
  if (params.to !== undefined) query.set("to", String(params.to));
  if (params.proto) query.set("proto", params.proto);
  if (params.level) query.set("level", params.level);
  if (params.type) query.set("type", params.type);
  if (params.limit) query.set("limit", String(params.limit));
  const suffix = query.toString() ? `?${query.toString()}` : "";
  return getJson(`/api/events${suffix}`);
}

async function getJson<T>(url: string): Promise<T> {
  const response = await fetch(url, { cache: "no-store" });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<T>;
}
import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import type { FastifyInstance } from "fastify";
import type { StreamStore } from "../state/store";
import { config } from "../config";
import { MaintenanceSettings, SettingsConflictError, SettingsValidationError, type RuntimeSettings } from "../maintenanceSettings";
import { AlertsSettings, AlertsConflictError, AlertsValidationError } from "../alertsSettings";
import { ProtocolMapSettings, ProtocolMapConflictError, ProtocolMapValidationError } from "../protocolMapSettings";
import { queryInterfaceMetricsHistory, queryMetricsSnapshotAt, queryStreamMetricsHistory } from "../history/query";
import { queryTimelineHistory } from "../history/timeline_query";
import { queryLatestTimelineAvailabilityAtOrBefore } from "../history/timeline_availability_query";
import { queryEventsHistory } from "../history/events_query";
import { queryProjectedTopologyAt } from "../history/topology_state_query";
import { enrichProjectedStreamSnapshot, queryProjectedStreamsAt } from "../history/stream_state_query";
import type { DashboardLayout, TimelineRow, TimelineViewResponse } from "../types";

export async function registerRoutes(
  app: FastifyInstance,
  store: StreamStore,
  maintenanceSettings: MaintenanceSettings,
  alertsSettings: AlertsSettings | undefined,
  protocolMapSettings: ProtocolMapSettings | undefined,
  applyRuntimeSettings: (values: RuntimeSettings) => void
) {
  app.addHook("onSend", async (_request, reply, payload) => {
    reply.header("Cache-Control", "no-store");
    return payload;
  });

  app.get("/api/config", async () => ({
    lostRetentionSec: config.lostRetentionSec,
    historyWindowSec: config.historyWindowSec,
    staleAfterSec: config.staleAfterSec,
    diagnosticLog: config.diagnosticLog
  }));

  app.get("/api/live", async () => ({
    observedAt: await queryLatestTimelineAvailabilityAtOrBefore(Date.now() / 1000) ?? null
  }));

  app.get("/api/maintenance/frontend-settings", async () => maintenanceSettings.get());

  app.put<{ Body: { revision?: unknown; values?: unknown } }>("/api/maintenance/frontend-settings", async (request, reply) => {
    try {
      const updated = await maintenanceSettings.update(request.body?.revision, request.body?.values);
      applyRuntimeSettings(updated.values);
      return updated;
    } catch (error) {
      if (error instanceof SettingsConflictError) return reply.code(409).send({ error: error.message });
      if (error instanceof SettingsValidationError) return reply.code(400).send({ error: error.message });
      request.log.error({ error }, "failed to persist maintenance settings");
      return reply.code(500).send({ error: "failed to persist settings" });
    }
  });

  app.get("/api/maintenance/alerts", async (_request, reply) => {
    if (!alertsSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await alertsSettings.get(); }
    catch (error) { return reply.code(400).send({ error: error instanceof Error ? error.message : "failed to read alerts config" }); }
  });

  app.put<{ Body: { revision?: unknown; document?: unknown } }>("/api/maintenance/alerts", async (request, reply) => {
    if (!alertsSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await alertsSettings.update({ revision: request.body?.revision, document: request.body?.document }); }
    catch (error) {
      if (error instanceof AlertsConflictError) return reply.code(409).send({ error: error.message });
      if (error instanceof AlertsValidationError) return reply.code(400).send({ error: error.message });
      request.log.error({ error }, "failed to persist alerts config");
      return reply.code(500).send({ error: "failed to persist alerts config" });
    }
  });

  app.get("/api/maintenance/protocol-map", async (_request, reply) => {
    if(!protocolMapSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await protocolMapSettings.get(); }
    catch(error) { return reply.code(400).send({ error: error instanceof Error ? error.message : "failed to read protocol map" }); }
  });

  app.put<{ Body: { revision?: unknown; path?: unknown; document?: unknown } }>("/api/maintenance/protocol-map", async (request, reply) => {
    if(!protocolMapSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await protocolMapSettings.update({ revision: request.body?.revision, path: request.body?.path, document: request.body?.document }); }
    catch(error) {
      if(error instanceof ProtocolMapConflictError) return reply.code(409).send({ error: error.message });
      if(error instanceof ProtocolMapValidationError) return reply.code(400).send({ error: error.message });
      request.log.error({ error }, "failed to persist protocol map");
      return reply.code(500).send({ error: "failed to persist protocol map" });
    }
  });

  app.get("/api/summary", async () => store.getSummary());

  app.get("/api/dashboard-layouts", async () => readDashboardLayouts());

  app.put<{ Body: DashboardLayout[] }>("/api/dashboard-layouts", async (request) => {
    const layouts = Array.isArray(request.body) ? request.body : [DEFAULT_DASHBOARD_LAYOUT];
    await writeDashboardLayouts(layouts);
    return readDashboardLayouts();
  });


  app.get("/api/bootstrap", async () => ({
    streams: store.listStreams(),
    interfaces: store.listInterfaces(),
    timeline: store.listTimeline(),
    summary: store.getSummary(),
    events: store.listEvents({ limit: 100 })
  }));

  app.get("/api/interfaces", async () => store.listInterfaces());

  app.get<{ Params: { interfaceId: string }; Querystring: { windowSec?: string; from?: string; to?: string } }>(
    "/api/interfaces/:interfaceId/metrics",
    async (request, reply) => {
      const interfaceId = Number(request.params.interfaceId);
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      if (!Number.isInteger(interfaceId)) return reply.code(400).send({ error: "invalid interface id" });
      const metrics = store.getInterfaceMetrics(interfaceId, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

  app.get<{ Params: { key: string }; Querystring: { windowSec?: string; from?: string; to?: string } }>(
    "/api/interfaces/by-key/:key/metrics",
    async (request, reply) => {
      const key = decodeURIComponent(request.params.key);
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      const from = request.query.from ? Number(request.query.from) : undefined;
      const to = request.query.to ? Number(request.query.to) : undefined;
      if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
        const metrics = await queryInterfaceMetricsHistory({ key, from: from!, to: to! });
        if (!metrics) return reply.code(404).send({ error: "interface history not available" });
        return metrics;
      }
      const metrics = store.getInterfaceMetricsByKey(key, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

  app.get<{ Querystring: { time?: string } }>("/api/streams", async (request, reply) => {
    const time = request.query.time ? Number(request.query.time) : undefined;
    if (Number.isFinite(time)) {
      let snapshot = await queryProjectedStreamsAt(config.streamStateDir, time!);
      if (!snapshot) return reply.code(404).send({ error: "streams snapshot not available" });
      const metricsSnapshot = await queryMetricsSnapshotAt(time!);
      if (metricsSnapshot) snapshot = enrichProjectedStreamSnapshot(snapshot, metricsSnapshot.interfaces, metricsSnapshot.metrics);
      return snapshot;
    }
    return store.listStreams();
  });

  app.get<{ Querystring: { time?: string } }>("/api/topology", async (request, reply) => {
    const time = request.query.time ? Number(request.query.time) : undefined;
    if (Number.isFinite(time)) {
      const snapshot = await queryProjectedTopologyAt({
        checkpointDir: config.topologyCheckpointDir,
        updatesDir: config.topologyUpdatesDir,
        time: time!
      });
      if (!snapshot) return reply.code(404).send({ error: "topology snapshot not available" });
      return snapshot;
    }
    const topology = store.getTopology();
    if (config.diagnosticLog) console.error("[STM_DIAG] api topology status=" + (topology ? "200" : "404") + " nodes=" + (topology?.nodes.length ?? 0) + " edges=" + (topology?.edges.length ?? 0));
    if (!topology) return reply.code(404).send({ error: "topology snapshot not available" });
    return topology;
  });

  app.get<{ Querystring: { from?: string; to?: string; includeFlows?: string } }>("/api/timeline", async (request): Promise<TimelineViewResponse> => {
    const from = request.query.from ? Number(request.query.from) : undefined;
    const to = request.query.to ? Number(request.query.to) : undefined;
    if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
      return queryTimelineHistory({
        from: from!,
        to: to!,
        includeFlows: request.query.includeFlows !== "0"
      });
    }
    const rows = store.listTimeline();

