import { useEffect, useState, type FormEvent } from "react";
import { getMaintenanceSettings, saveMaintenanceSettings } from "../api/client";
import type { AppConfig, MaintenanceSettingsResponse } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type MaintenancePaneProps = {
  refreshToken: number;
  onApplied: (config: AppConfig) => void;
};

export function MaintenancePane({ refreshToken, onApplied }: MaintenancePaneProps) {
  const [settings, setSettings] = useState<MaintenanceSettingsResponse | null>(null);
  const [draft, setDraft] = useState<AppConfig | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");

  useEffect(() => {
    let cancelled = false;
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      if (cancelled) return;
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      if (cancelled) return;
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
    return () => { cancelled = true; };
  }, [refreshToken]);

  const reload = () => {
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings || !draft) return;
    setState("saving");
    setMessage("");
    void saveMaintenanceSettings(settings.revision, draft).then((next) => {
      setSettings(next);
      setDraft(next.values);
      onApplied(next.values);
      setState("saved");
      setMessage("Saved and applied to all connected clients.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to save settings");
    });
  };

  return (
    <PaneFrame
      className="maintenance-frame"
      header={<PaneHeader
        title="Maintenance"
        icon="maintenance"
        meta="Shared frontend runtime settings"
        actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={reload} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>}
      />}
    >
      <form className="maintenance-form" onSubmit={submit}>
        <div className="maintenance-intro">Changes are validated by the server, persisted for the next restart, and applied immediately to every connected client.</div>
        {settings?.sections.map((section) => (
          <section key={section.id} className="maintenance-section">
            <div className="maintenance-section-copy">
              <h2>{section.label}</h2>
              {section.description && <p>{section.description}</p>}
            </div>
            <div className="maintenance-table-wrap">
              <table className="maintenance-table">
                <thead><tr><th>Parameter</th><th>Value</th><th>Range</th><th>Apply</th></tr></thead>
                <tbody>
                  {section.settings.map((setting) => {
                    const value = draft?.[setting.key];
                    return (
                      <tr key={setting.key}>
                        <th scope="row"><span>{setting.label}</span>{setting.description && <small>{setting.description}</small>}</th>
                        <td>
                          {setting.type === "boolean" ? (
                            <button
                              type="button"
                              role="switch"
                              aria-checked={Boolean(value)}
                              className={`maintenance-switch ${value ? "is-on" : "is-off"}`}
                              disabled={!draft || state === "saving"}
                              onClick={() => setDraft((current) => current ? { ...current, [setting.key]: !current[setting.key] } : current)}
                            >
                              <span className="maintenance-switch-track" aria-hidden="true"><span className="maintenance-switch-thumb" /></span>
                              <span>{value ? "On" : "Off"}</span>
                            </button>
                          ) : setting.type === "select" ? (
                            <select value={String(value ?? "")} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)}>
                              {setting.options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                            </select>
                          ) : (
                            <input type="number" value={String(value ?? "")} min={setting.min} max={setting.max} step={setting.step ?? 1} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)} />
                          )}
                          {setting.unit && <span className="maintenance-unit">{setting.unit}</span>}
                        </td>
                        <td>{setting.type === "boolean" ? "—" : `${setting.min ?? "—"}–${setting.max ?? "—"}`}</td>
                        <td><span className={`maintenance-apply maintenance-apply-${setting.apply}`}>{setting.apply}</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>
        ))}
        <footer className="maintenance-actions">
          <span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading settings…" : message}</span>
          <button type="submit" className="maintenance-save-button button-with-icon" disabled={!draft || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Saving…" : "Save and apply"}</button>
        </footer>
      </form>
    </PaneFrame>
  );
}
import { useEffect, useState, type FormEvent } from "react";
import { getProtocolMapSettings, saveProtocolMapSettings } from "../api/client";
import type { ProtocolMapDocument, ProtocolMapResponse, ProtocolRule } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Row = Omit<ProtocolRule, "proto"> & { proto: ProtocolRule["proto"] | "RTP-FEC"; target: "endpoint" | "host"; value: string; port: string; vlanMode: "any" | "untagged" | "id"; vlanId: string };

const modes = ["all", "configured_only", "configured_plus_other"] as const;

export function ProtocolMapPane() {
  const [settings, setSettings] = useState<ProtocolMapResponse | null>(null);
  const [path, setPath] = useState("");
  const [mode, setMode] = useState<ProtocolMapDocument["observe_mode"]>("all");
  const [rows, setRows] = useState<Row[]>([]);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");
  const locked = mode === "all";

  const load = () => {
    setState("loading");
    void getProtocolMapSettings().then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load protocol map"); });
  };
  useEffect(load, []);

  const updateRow = (index: number, patch: Partial<Row>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => setRows((current) => [...current, { enabled: true, observe: true, proto: "RTP", target: "endpoint", value: "", port: "", vlanMode: "any", vlanId: "" }]);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving"); setMessage("");
    const document: ProtocolMapDocument = { observe_mode: mode, protocols: rows.map(fromRow) };
    void saveProtocolMapSettings(settings.revision, path, document).then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("saved"); setMessage("Saved. Restart STM to apply the new protocol map.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to apply protocol map"); });
  };

  return <PaneFrame className="maintenance-frame protocol-map-frame" header={<PaneHeader title="Protocol map" icon="protocolMap" meta="STM classification and observation rules" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form" onSubmit={submit}>
      <div className="maintenance-intro">Apply writes the selected protocol map and updates STM&apos;s config reference. STM restart is required before the change takes effect.</div>
      <section className="maintenance-section"><div className="maintenance-section-copy"><h2>Protocol map file</h2><p>Path relative to the STM unified config file.</p></div><div className="protocol-map-controls"><label>Path<input value={path} disabled={state === "saving"} onChange={(event) => setPath(event.target.value)} /></label><label>Observe mode<select value={mode} disabled={state === "saving"} onChange={(event) => setMode(event.target.value as ProtocolMapDocument["observe_mode"])}>{modes.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div></section>
      {locked && <div className="protocol-map-notice">all observes every classified stream. Saved rules remain available but cannot be edited in this mode.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table protocol-map-table"><thead><tr><th>#</th><th>Enabled</th><th>Protocol</th><th>Target</th><th>Address / domain</th><th>Port</th><th>VLAN</th><th>Stream name</th><th /></tr></thead><tbody>{rows.map((row, index) => <tr key={index}><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={`maintenance-switch ${row.enabled !== false ? "is-on" : "is-off"}`} disabled={locked || state === "saving"} onClick={() => updateRow(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><select value={row.proto} disabled={locked || state === "saving"} onChange={(event) => { const proto = event.target.value as Row["proto"]; updateRow(index, { proto, target: proto === "HLS" ? row.target : "endpoint", fec: proto === "RTP-FEC" }); }}><option value="RTP">RTP</option><option value="RTP-FEC">RTP-FEC</option><option value="SRT">SRT</option><option value="HLS">HLS</option></select></td><td><select value={row.target} disabled={locked || state === "saving" || row.proto !== "HLS"} onChange={(event) => updateRow(index, { target: event.target.value as Row["target"], value: "", port: "" })}><option value="endpoint">Endpoint</option><option value="host">Host</option></select></td><td><input value={row.value} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { value: event.target.value })} placeholder={row.target === "host" ? "media.example.com" : "239.1.1.1"} /></td><td>{row.target === "endpoint" && <input type="number" min="1" max="65535" value={row.port} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { port: event.target.value })} />}</td><td><select value={row.vlanMode} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanMode: event.target.value as Row["vlanMode"] })}><option value="any">Any</option><option value="untagged">Untagged</option><option value="id">ID</option></select>{row.vlanMode === "id" && <input type="number" min="0" max="4094" value={row.vlanId} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanId: event.target.value })} />}</td><td><input value={row.stream_name ?? ""} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { stream_name: event.target.value })} /></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={locked || state === "saving"} onClick={() => removeRow(index)} aria-label="Delete protocol rule" title="Delete protocol rule"><Icon name="delete" size={16} /></button></td></tr>)}</tbody></table></div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={locked || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add row</button></div></section>
      <footer className="maintenance-actions"><span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading protocol map…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

function toRow(rule: ProtocolRule): Row {
  const endpoint = first(rule.endpoints); const host = first(rule.hosts) || first(rule.domains); const target = host ? "host" : "endpoint"; const split = endpoint ? splitEndpoint(endpoint) : { value: host ?? "", port: "" }; const vlan = rule.vlan === null ? { vlanMode: "untagged" as const, vlanId: "" } : rule.vlan === undefined ? { vlanMode: "any" as const, vlanId: "" } : { vlanMode: "id" as const, vlanId: String(rule.vlan) };
  return { ...rule, proto: rule.proto === "RTP" && rule.fec === true ? "RTP-FEC" : rule.proto, target, value: split.value, port: split.port, ...vlan };
}
function fromRow(row: Row): ProtocolRule {
  const { target, value, port, vlanMode, vlanId, proto, ...rule } = row; const next: ProtocolRule = { ...rule, observe: rule.observe ?? true, enabled: rule.enabled !== false, proto: proto === "RTP-FEC" ? "RTP" : proto, ...(vlanMode === "untagged" ? { vlan: null } : vlanMode === "id" ? { vlan: Number(vlanId) } : {}) };
  if (target === "host") next.hosts = [value.trim()]; else next.endpoints = [`${formatHost(value.trim())}:${port}`];
  if (proto === "RTP-FEC") next.fec = true; else delete next.fec;
