      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const isLatestAvailable = latestAvailableTimeSec !== null;
  const contextTimeSec = dashboardTimeContextActive ? dashboardContextTimeSec : tabContextTimeSec;
  const contextPaused = dashboardTimeContextActive ? dashboardPaused : paused;
  const contextStateLabel = dashboardTimeContextActive && dashboardSelectedTimeSec !== null
    ? " · " + formatTimeTravel(dashboardSelectedTimeSec, locale)
    : !dashboardTimeContextActive && selectedTimeSec !== null
      ? " · " + formatTimeTravel(selectedTimeSec, locale)
      : contextPaused
        ? " · display frozen"
        : isLatestAvailable
          ? " · latest available"
          : !summary.updatedAt
            ? " · waiting for data"
            : "";
  const contextUpdatedLabel = t("header.updated", { time: summary.updatedAt ? formatRelativeTime(summary.updatedAt, locale) : t("common.waiting") }) + contextStateLabel;
  const liveLabel = dashboardTimeContextActive && dashboardSelectedTimeSec !== null
    ? "Time travel"
    : !dashboardTimeContextActive && selectedTimeSec !== null
      ? "Time travel"
      : contextPaused
        ? "Paused"
        : isLatestAvailable
          ? t("common.latestAvailable")
          : summary.updatedAt
            ? t("common.live")
            : t("common.waiting");
          </button>
          <nav className="menu-rail-nav" aria-label="Primary">
            {MENU_PLACEMENTS.map((placement) => (
              <div key={placement} className={`menu-group menu-group-${placement}`}>
                {MENU_ITEMS.filter((item) => item.placement === placement).map((item) => item.type === "separator" ? (
                  <div key={item.key} className="menu-separator" role="separator" />
                ) : (
                  <button
                    key={item.key}
                    type="button"
                    className={`menu-item ${item.key === activeTab ? "active" : ""}`}
                    title={item.label}
                    onClick={() => setActiveTab(item.key)}
                    aria-pressed={item.key === activeTab}
                  >
                    <span className="menu-item-icon"><Icon name={item.icon} size={20} /></span>
                    {menuExpanded && (
                      <span className="menu-item-copy">
                        <strong>{item.label}</strong>
                        <small>{item.hint}</small>
                      </span>
                    )}
                  </button>
        </div>
      </div>
      {/* Strong guard against browser history swipe gestures during splitter drags; remove if it interferes with normal dragging. */}
      {resizingPane && <div className={`resize-capture resize-capture-${resizingPane}`} aria-hidden="true" />}
    </main>
  );
}

function navMessageKey(tab: MainTab) {
  return tab === "detail" ? "nav.inspector" : tab === "alerts" ? "nav.alertRules" : tab === "protocol-map" ? "nav.protocolMap" : `nav.${tab}`;
}

function titleForDashboardView(viewType: DashboardViewType) {
  switch (viewType) {
    case "streams": return "Streams";
    case "detail": return "Inspector";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
  }
}

function nextDashboardY(cells: DashboardCell[]) {
  return cells.reduce((max, cell) => Math.max(max, cell.grid.y + cell.grid.h), 0);
}

function clampDashboardCell(cell: DashboardCell, columns: number): DashboardCell {
  const width = Math.max(2, Math.min(columns, Math.round(cell.grid.w)));
  const height = Math.max(3, Math.min(40, Math.round(cell.grid.h)));
  return {
    ...cell,
    title: cell.title || titleForDashboardView(cell.viewType),
    grid: {
      x: Math.max(0, Math.min(columns - width, Math.round(cell.grid.x))),
      y: Math.max(0, Math.min(200, Math.round(cell.grid.y))),
      w: width,
      h: height
    }
  };
}

function compareTimelineRows(a: TimelineRow, b: TimelineRow, streamOrder: Map<string, number>) {
  const positionA = streamOrder.get(a.streamKey);
  const positionB = streamOrder.get(b.streamKey);
  if (positionA !== undefined || positionB !== undefined) {
    if (positionA === undefined) return 1;
    if (positionB === undefined) return -1;
    return positionA - positionB;
  }
  return b.lastSeen - a.lastSeen || a.label.localeCompare(b.label) || a.streamKey.localeCompare(b.streamKey);
}

function timelineRowKey(row: TimelineRow) {
  if (row.rowType === "flow") {
    return `flow:${row.parentStreamKey ?? row.streamKey}::${row.flowKey ?? row.streamKey}`;
  }
  return `stream:${row.streamKey}`;
}

function formatTimeTravel(epochSec: number, locale: string) {
  return new Date(epochSec * 1000).toLocaleString(locale, { hour12: false });
}

