import type { FlowMetricsResponse, MetricDescriptor, StreamMetricsResponse, StreamState, TimeSeriesMetric } from "../types/api";
import { formatBitrate, formatNumber, formatRelativeTime } from "./format";
import { MetricChart } from "./MetricChart";
import { Icon } from "./ui/Icon";
import { useI18n } from "../i18n";

type DetailPaneProps = {
  stream: StreamState | null;
  metrics: StreamMetricsResponse | null;
  selectedFlowKey?: string | null;
  metricsRange: string;
  onChangeMetricsRange: (range: string) => void;
  mode: "overview" | "detail";
  onChangeMode: (mode: "overview" | "detail") => void;
  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
  embedded?: boolean;
  onOpenTargetPicker?: () => void;
};

const FLOW_ROLE_ACCENTS: Record<string, string> = {
  media: "#7fd4c7",
  fec_row: "#62b7c3",
  fec_col: "#6e97c7",
  control: "#5f7fb9",
  mixed: "#6fa7d4",
  default: "#7f98b5"
};

export function DetailPane({
  stream,
  metrics,
  selectedFlowKey,
  metricsRange,
  onChangeMetricsRange,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls,
  embedded = false,
  onOpenTargetPicker
}: DetailPaneProps) {
  const { t } = useI18n();
  if (!stream) {
    return <aside className="detail-pane empty-state">
      <div>
        <p>Select a stream to inspect bitrate and flow metrics.</p>
        {onOpenTargetPicker && <button type="button" className="button-with-icon dashboard-detail-target inspector-target-select" onClick={onOpenTargetPicker}><Icon name="targetFollow" size={15} />{t("dashboard.selectTargetButton")}</button>}
      </div>
    </aside>;
  }

  const selectedFlow = selectedFlowKey ? stream.flows.find((flow) => flow.flowKey === selectedFlowKey) : undefined;
  const headerTargetLabel = selectedFlow
    ? stream.proto + " " + (selectedFlow.endpointSrc || "-") + " → " + (selectedFlow.endpointDst || "-")
    : stream.label;
  const descriptors = metrics?.descriptors ?? [];
  const visibleFlows = selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows;
  const visibleMetrics = metrics && selectedFlowKey
    ? { ...metrics, flows: metrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) }
    : metrics;
  const primary = descriptors.filter((descriptor) => descriptor.category === "primary");
  const secondary = descriptors.filter((descriptor) => descriptor.category === "secondary");
  const stats = descriptors.filter((descriptor) => descriptor.category === "stat");

  return (
    <aside className={["detail-pane", mode === "overview" ? "graph-mode" : "", embedded ? "detail-pane-embedded" : ""].filter(Boolean).join(" ")}>
      {!embedded && <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <Icon className="pane-header-icon" name="detail" size={14} />
          <h2>{headerTargetLabel}</h2>
          <p>{selectedFlowKey ? "Filtered to one flow" : `${stream.flowCount} flow${stream.flowCount === 1 ? "" : "s"}`} / last seen {formatRelativeTime(stream.lastSeen)}</p>
        </div>
        <div className="detail-header-actions">
          {onOpenTargetPicker && <button type="button" className="button-with-icon dashboard-detail-target inspector-target-select" onClick={onOpenTargetPicker}><Icon name="targetFollow" size={15} />{t("dashboard.selectTargetButton")}</button>}
          <label className="detail-range-select">
            <span>Range</span>
            <select value={metricsRange} onChange={(event) => onChangeMetricsRange(event.target.value)}>
              <option value="24h">24h</option>
              <option value="12h">12h</option>
              <option value="6h">6h</option>
              <option value="3h">3h</option>
              <option value="1h">1h</option>
              <option value="30m">30m</option>
              <option value="10m">10m</option>
              <option value="5m">5m</option>
              <option value="1m">1m</option>
            </select>
          </label>
          <div className="detail-mode-tabs" role="tablist" aria-label="Inspector mode">
            <button className={mode === "overview" ? "active" : ""} onClick={() => onChangeMode("overview")} type="button">Overview</button>
            <button className={mode === "detail" ? "active" : ""} onClick={() => onChangeMode("detail")} type="button">Metrics</button>
          </div>
          {showWidthControls && (
            <div className="pane-width-controls" aria-label="Inspector width controls">
              <button type="button" className={`size-button size-button-v size-button-left ${isWidthMaximized ? "active" : ""}`} onClick={onMaximizeWidth} aria-pressed={isWidthMaximized} title="Maximize Inspector pane"><Icon name="widthMaximize" size={16} /></button>
              <button type="button" className={`size-button size-button-v size-button-center ${isWidthRestored ? "active" : ""}`} onClick={onRestoreWidth} aria-pressed={isWidthRestored} title="Restore Inspector pane width"><Icon name="widthRestore" size={16} /></button>
              <button type="button" className={`size-button size-button-v size-button-right ${isWidthMinimized ? "active" : ""}`} onClick={onMinimizeWidth} aria-pressed={isWidthMinimized} title="Shrink Inspector pane"><Icon name="widthMinimize" size={16} /></button>
            </div>
          )}
        </div>
      </header>}

      <div className="detail-body">
        {mode === "overview" ? (
          <GraphMode
            stream={stream}
            metrics={visibleMetrics}
            visibleFlows={visibleFlows}
            descriptors={[...primary, ...secondary]}
            selectedFlowKey={selectedFlowKey}
          />
        ) : (
          <>
            <div className="overview-grid">
              <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
              <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
              <Stat label="Roles" value={selectedFlowKey ? (visibleFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")} />
            </div>

            <section className="flow-table-card">
              <h3>Flows</h3>
              <div className="flow-table">
                {visibleFlows.map((flow) => (
                  <div className="flow-row" key={flow.flowKey}>
                    <strong>{flow.role}</strong>
                    <span>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span>
                    <span>{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span>
                  </div>
                ))}
              </div>
            </section>

            {stats.length > 0 && <StatsSection descriptors={stats} metrics={visibleMetrics} />}

            {!selectedFlowKey && <MetricChart title="Stream Bitrate" metric={metrics?.streamBitrate} />}

            {primary.map((descriptor) => (
              <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} />
            ))}

            {secondary.length > 0 && (
              <details className="more-metrics">
                <summary>More numeric metrics</summary>
                {secondary.slice(0, 12).map((descriptor) => (
                  <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} compact />
                ))}
              </details>
            )}
          </>
        )}
      </div>
    </aside>
  );
}

function GraphMode({
  stream,
  metrics,
  visibleFlows,
  descriptors,
  selectedFlowKey
}: {
  stream: StreamState;
  metrics: StreamMetricsResponse | null;
  visibleFlows: StreamState["flows"];
  descriptors: MetricDescriptor[];
  selectedFlowKey?: string | null;
}) {
  const nonBitrateDescriptors = descriptors
    .filter((descriptor) => descriptor.key !== "bitrate")
    .sort((a, b) => a.priority - b.priority);
  const metricByFlowKey = new Map((metrics?.flows ?? []).map((flow) => [flow.flowKey, flow]));
  const streamBitrate = metrics?.streamBitrate;

  return (
    <div className="graph-mode-layout">
      <section className="graph-summary-band">
        <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
        <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
        <Stat label="Flows" value={String(visibleFlows.length)} />
        <Stat label="Roles" value={selectedFlowKey ? (visibleFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")} />
      </section>

      {!selectedFlowKey && (
        <section className="graph-hero-card">
          <MetricChart title="Stream Bitrate" metric={streamBitrate} height={96} compact fillHeight color="#66d9ef" />
        </section>
      )}

      <section className={`graph-flow-grid ${visibleFlows.length === 1 ? "single" : ""}`}>
        {visibleFlows.map((flow) => {
          const flowMetrics = metricByFlowKey.get(flow.flowKey);
          const charts = [
            flowMetrics?.metrics.bitrate ? { key: "bitrate", label: "Bitrate", metric: flowMetrics.metrics.bitrate } : null,
            ...nonBitrateDescriptors
              .map((descriptor) => {
                const metric = flowMetrics?.metrics[descriptor.key];
                return metric ? { key: descriptor.key, label: descriptor.label, metric } : null;
              })
              .filter((item): item is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(item))
          ].filter((item): item is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(item));

          return (
            <GraphFlowCard
              key={flow.flowKey}
              flow={flow}
              metrics={flowMetrics}
              charts={charts}
            />
          );
        })}
      </section>
    </div>
  );
}

function GraphFlowCard({
  flow,
  metrics,
  charts
}: {
  flow: StreamState["flows"][number];
  metrics?: FlowMetricsResponse;
  charts: Array<{ key: string; label: string; metric: TimeSeriesMetric }>;
}) {
  const accent = flowAccent(flow.role);
  const bitrate = metrics?.metrics.bitrate?.points.at(-1)?.avg
    ?? metrics?.metrics.bitrate?.points.at(-1)?.value
    ?? flow.metrics.bitrate?.value
    ?? flow.metrics.bitrate?.avg;

  return (
    <section className="graph-flow-card" style={{ borderTopColor: accent }}>
      <div className="graph-flow-card-header">
        <div>
          <strong>{flow.role}</strong>
          <p>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</p>
        </div>
        <span className="graph-flow-rate">{formatBitrate(bitrate)}</span>
      </div>
      <div className={`graph-card-grid ${charts.length === 1 ? "single" : ""}`}>
        {charts.map((chart) => (
          <MetricChart
            key={`${flow.flowKey}:${chart.key}`}
            title={chart.label}
            metric={chart.metric}
            height={chart.key === "bitrate" ? 64 : 52}
            compact
            fillHeight
            color={chart.key === "bitrate" ? accent : colorForMetric(chart.key)}
          />
        ))}
      </div>
    </section>
  );
}

function FlowMetricGroup({ descriptor, metrics, compact = false }: { descriptor: MetricDescriptor; metrics: StreamMetricsResponse | null; compact?: boolean }) {
  const flowMetrics = metrics?.flows
    .map((flow) => ({ flow, metric: flow.metrics[descriptor.key] }))
    .filter((item): item is { flow: NonNullable<typeof metrics>["flows"][number]; metric: TimeSeriesMetric } => Boolean(item.metric));

  if (!flowMetrics || flowMetrics.length === 0) return null;

  return (
    <section className={compact ? "metric-group compact" : "metric-group"}>
      <h3>{descriptor.label}</h3>
      <div className="chart-stack">
        {flowMetrics.map(({ flow, metric }) => (
          <MetricChart key={`${flow.flowKey}:${descriptor.key}`} title={flow.label} metric={metric} height={compact ? 130 : 170} color={colorForMetric(descriptor.key)} />
        ))}
      </div>
    </section>
  );
}

function StatsSection({ descriptors, metrics }: { descriptors: MetricDescriptor[]; metrics: StreamMetricsResponse | null }) {
  const values = metrics?.flows.flatMap((flow) =>
    descriptors.flatMap((descriptor) => {
      const latest = flow.metrics[descriptor.key]?.points.at(-1);
      const value = latest?.value ?? latest?.avg;
      return value === undefined ? [] : [{ key: `${flow.flowKey}:${descriptor.key}`, label: `${flow.role} ${descriptor.label}`, value }];
    })
  ) ?? [];

  if (values.length === 0) return null;
  return (
    <section className="stats-section">
      <h3>Stats</h3>
      <div className="stats-grid">
        {values.slice(0, 18).map((item) => <Stat key={item.key} label={item.label} value={formatNumber(item.value)} />)}
      </div>
    </section>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return <div className="stat-card"><span>{label}</span><strong>{value}</strong></div>;
}

function flowAccent(role: string) {
  return FLOW_ROLE_ACCENTS[role] ?? FLOW_ROLE_ACCENTS.default;
}

function colorForMetric(key: string) {
  const palette: Record<string, string> = {
    bitrate: "#66d9ef",
    packet_rate: "#8bd17c",
    jitter: "#d6b66f",
    rtt: "#d98b7f",
    rttvar: "#c58bd6",
    bandwidth: "#7fa7d9",
    rate: "#70c7b0",
    rcvrate: "#9ca4d9",
    interval: "#d69f73",
    clock_skew: "#b5c46f",
    nak_seqno: "#d184a8"
  };
  const root = key.split(".")[0];
  return palette[root] ?? fallbackMetricColor(root);
}

function fallbackMetricColor(key: string) {
  const colors = ["#8fb8d8", "#91c7a3", "#c9b878", "#d09787", "#a995d0", "#78c2bf", "#c99ac0"];
  let hash = 0;
  for (const char of key) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return colors[hash % colors.length];
}
function streamEndpointLabel(stream: StreamListItem) {
  const primaryFlow = stream.flows.find((flow) => flow.role === "media") ?? stream.flows[0];
  return stream.sessionDst
    ?? stream.endpointB
    ?? primaryFlow?.endpointDst
    ?? stream.endpointA
    ?? primaryFlow?.endpointSrc
    ?? endpointFromStreamKey(stream.streamKey)
    ?? "Endpoint unknown";
}

function endpointFromStreamKey(streamKey: string) {
  const fields = new Map(streamKey.split("|").map((part) => {
    const separator = part.indexOf("=");
    return separator < 0 ? ["", ""] : [part.slice(0, separator), part.slice(separator + 1)];
  }));
  for (const key of ["session_dst", "ep", "b", "dst", "a", "src"]) {
    const value = fields.get(key);
    if (value) return value;
  }
  return undefined;
}

function LastSeen({ epochSec }: { epochSec?: number }) {
  const absoluteDateTime = formatAbsoluteDateTime(epochSec);
  return <time className="stream-last-seen" dateTime={epochSec ? new Date(epochSec * 1000).toISOString() : undefined} title={absoluteDateTime}>{formatRelativeTime(epochSec)}</time>;
}

function DescendantCountBadge({ count }: { count: number }) {
  return <span className="tree-count-badge">{count}</span>;
}

function displayFlowRole(role: string) {
  if (["default", "flow", "unknown"].includes(role)) return undefined;
  return role.replace("_", " ");
}

function streamBitrateOf(stream: StreamListItem) {
  return stream.bitrate.value ?? stream.bitrate.avg ?? 0;
}

function protoAccentColor(proto: string) {
  switch (proto.toUpperCase()) {
    case "RTP":
      return "#f7c873";
    case "SRT":
      return "#7fd4c7";
    case "HLS":
      return "#87abd5";
    default:
      return "#a8b0ba";
  }
}

function buildTopBitrateEntries(streams: StreamListItem[]) {
  const sorted = streams
    .map((stream) => ({
      key: stream.streamKey,
      label: compactStreamLabel(stream),
      value: streamBitrateOf(stream)
    }))
    .filter((entry) => entry.value > 0)
    .sort((a, b) => b.value - a.value);
  const total = sorted.reduce((sum, entry) => sum + entry.value, 0);
  const top = sorted.slice(0, 5);
  const others = sorted.slice(5).reduce((sum, entry) => sum + entry.value, 0);
  const entries = others > 0 ? [...top, { key: "others", label: "Others", value: others }] : top;

  if (total === 0) return [{ key: "none", label: "No bitrate", value: 0, percent: 0 }];
  return entries.map((entry) => ({
    ...entry,
    percent: Math.round((entry.value / total) * 100)
  }));
}

function compactStreamLabel(stream: StreamListItem) {
  const label = stream.label || stream.streamKey;
  return label.length > 22 ? `${label.slice(0, 19)}...` : label;
}

function StreamSummaryChart({ stream, scaleMax }: { stream: StreamListItem; scaleMax: number }) {
  const width = 150;
  const height = 24;
  const totalValues = normalizeSeries(stream.sparkline);
  const count = totalValues.length;
  const flowSeries = stream.flows.map((flow) => ({
    flowKey: flow.flowKey,
    role: flow.role,
    values: alignSeries(flow.sparkline, count)
  }));

  if (count === 0) return <div className="sparkline-empty" style={{ width, height }} />;

  const pointsFor = (values: Array<number | undefined>) => values.map((value, index) => {
    const clamped = Math.max(0, Math.min(scaleMax, value ?? 0));
    const x = count === 1 ? width : (index / (count - 1)) * width;
    const y = height - ((clamped / scaleMax) * (height - 4)) - 2;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");

  return (
    <svg className="stream-summary-chart" width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      {flowSeries.map((series) => (
        <polyline
          key={series.flowKey}
          points={pointsFor(series.values)}
          fill="none"
          stroke={flowBarColor(series.role)}
          strokeWidth="1.1"
          strokeLinejoin="round"
          strokeLinecap="round"
          opacity={0.95}
        />
      ))}
      <polyline points={pointsFor(totalValues)} fill="none" stroke={TOTAL_COLOR} strokeWidth="1.1" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

function normalizeSeries(values: number[]) {
  if (values.length >= 60) return values.slice(-60);
  return [...Array(Math.max(0, 60 - values.length)).fill(0), ...values];
}

function alignSeries(values: number[], count: number) {
  const tail = values.slice(-count);
  return [...Array(Math.max(0, count - tail.length)).fill(undefined), ...tail];
}

