type SparklineProps = {
  values: number[];
  width?: number;
  height?: number;
  minValue?: number;
  maxValue?: number;
  color?: string;
  strokeWidth?: number;
};

export function Sparkline({ values, width = 120, height = 30, minValue, maxValue, color, strokeWidth = 2 }: SparklineProps) {
  if (values.length === 0) return <div className="sparkline-empty" style={{ width, height }} />;

  const min = minValue ?? Math.min(...values);
  const max = maxValue ?? Math.max(...values);
  const range = max - min || 1;
  const points = values
    .map((value, index) => {
      const clamped = Math.max(min, Math.min(max, value));
      const x = values.length === 1 ? width : (index / (values.length - 1)) * width;
      const y = height - ((clamped - min) / range) * (height - 4) - 2;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");

  return (
    <svg className="sparkline" width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={color ? { color } : undefined}>
      <polyline points={points} fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}
import { useEffect, useRef } from "react";
import uPlot from "uplot";
import type { TimeSeriesMetric } from "../types/api";
import { formatNumber } from "./format";

type MetricChartProps = {
  title: string;
  metric?: TimeSeriesMetric;
  height?: number;
  color?: string;
  compact?: boolean;
  fillHeight?: boolean;
};

const syncKey = "stream-detail";

export function MetricChart({ title, metric, height = 190, color = "var(--chart-accent)", compact = false, fillHeight = false }: MetricChartProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<uPlot | null>(null);
  const hasData = Boolean(metric && metric.points.length > 0);
  const hasRangeBand = Boolean(metric && metric.points.some((point) => point.min != null && point.max != null && Math.abs(point.max - point.min) > Number.EPSILON));

  useEffect(() => {
    if (!hostRef.current || !metric || metric.points.length === 0) return;

    const styles = getComputedStyle(hostRef.current);
    const lineColor = resolveColor(hostRef.current, color, cssVar(styles, "--chart-accent", "#5b47d6"));
    const axisColor = cssVar(styles, "--chart-axis", "#778397");
    const gridColor = cssVar(styles, "--chart-grid", "rgba(87, 102, 120, .16)");
    const bandFill = toRgba(lineColor, compact ? 0.18 : 0.24);
    const rangeStroke = toRgba(lineColor, compact ? 0.28 : 0.34);
    const transparentStroke = toRgba(lineColor, 0);
    const chartHeight = chartHeightFor(hostRef.current, height, fillHeight);
    const options: uPlot.Options = {
      width: hostRef.current.clientWidth || 640,
      height: chartHeight,
      cursor: { sync: { key: syncKey } },
      scales: { x: { time: true } },
      legend: { show: !compact },
      axes: compact
        ? [
            { show: false },
            { show: false }
          ]
        : [
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor } },
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, values: (_u, values) => values.map((v) => formatNumber(v)) }
          ],
      series: [
        {},
        {
          label: "min",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        {
          label: "max",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        { label: "avg", stroke: lineColor, width: compact ? 1.3 : 2, points: { show: false } }
      ],
      bands: hasRangeBand ? [{ series: [1, 2], fill: bandFill }] : [],
      padding: compact ? [6, 4, 4, 4] : undefined
    } as uPlot.Options;

    chartRef.current?.destroy();
    chartRef.current = new uPlot(options, toUplotData(metric), hostRef.current);

    const resize = () => {
      if (hostRef.current && chartRef.current) {
        chartRef.current.setSize({
          width: Math.max(1, hostRef.current.clientWidth),
          height: chartHeightFor(hostRef.current, height, fillHeight)
        });
      }
    };
    const resizeObserver = new ResizeObserver(() => resize());
    resizeObserver.observe(hostRef.current);
    window.addEventListener("resize", resize);
    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", resize);
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, [metric?.key, hasData, hasRangeBand, height, color, compact, fillHeight]);

  useEffect(() => {
    if (!chartRef.current || !metric || metric.points.length === 0) return;
    chartRef.current.setData(toUplotData(metric));
  }, [metric]);

  return (
    <section className={`chart-card ${compact ? "compact-chart" : ""}`}>
      <div className="chart-header">
        <h3>{title}</h3>
        {!compact && <span>{metric?.unit ?? ""}</span>}
      </div>
      <div className={`chart-host ${compact ? "compact-grid-host" : ""}`} ref={hostRef} style={{ minHeight: fillHeight ? 0 : height }} />
      {!hasData && <div className="empty-chart chart-empty-overlay">No data</div>}
    </section>
  );
}

function cssVar(styles: CSSStyleDeclaration, name: string, fallback: string) {
  return styles.getPropertyValue(name).trim() || fallback;
}

function resolveColor(host: HTMLElement, color: string, fallback: string) {
  if (!color.startsWith("var(")) return color;
  const variableName = color.slice(4, -1).trim();
  if (!variableName) return fallback;
  return getComputedStyle(host).getPropertyValue(variableName).trim() || fallback;
}

function chartHeightFor(host: HTMLDivElement, fallback: number, fillHeight: boolean) {
  if (!fillHeight) return fallback;
  return Math.max(32, host.clientHeight || fallback);
}

function toUplotData(metric: TimeSeriesMetric): uPlot.AlignedData {
  const x = metric.points.map((point) => point.time);
  const min = metric.points.map((point) => point.min ?? point.avg ?? point.value ?? null);
  const max = metric.points.map((point) => point.max ?? point.avg ?? point.value ?? null);
  const avg = metric.points.map((point) => point.avg ?? point.value ?? null);
  return [x, min, max, avg] as uPlot.AlignedData;
}

function toRgba(hex: string, alpha: number) {
  const normalized = hex.replace("#", "");
  if (normalized.length !== 6) return hex;
  const r = Number.parseInt(normalized.slice(0, 2), 16);
  const g = Number.parseInt(normalized.slice(2, 4), 16);
  const b = Number.parseInt(normalized.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
