function displayFlowRole(role: string) {
  if (["default", "flow", "unknown"].includes(role)) return undefined;
  return role.replace("_", " ");
}

function streamBitrateOf(stream: StreamListItem) {
  return stream.bitrate.value ?? stream.bitrate.avg ?? 0;
}

function protoAccentColor(proto: string) {
  switch (proto.toUpperCase()) {
    case "RTP":
      return "#f7c873";
    case "SRT":
      return "#7fd4c7";
    case "HLS":
      return "#87abd5";
    default:
      return "#a8b0ba";
  }
}

function buildTopBitrateEntries(streams: StreamListItem[]) {
  const sorted = streams
    .map((stream) => ({
      key: stream.streamKey,
      label: compactStreamLabel(stream),
      value: streamBitrateOf(stream)
            <section className="stats-section">
              <h3>NIC Stats</h3>
              <div className="stats-grid">
                <Stat label="RX Packets" value={formatNumber(item.rx.packets.value ?? 0)} />
                <Stat label="TX Packets" value={formatNumber(item.tx.packets.value ?? 0)} />
                <Stat label="RX Drops" value={formatNumber(item.rx.dropped.value ?? 0)} />
                <Stat label="TX Drops" value={formatNumber(item.tx.dropped.value ?? 0)} />
                <Stat label="RX Errors" value={formatNumber(item.rx.errors.value ?? 0)} />
                <Stat label="TX Errors" value={formatNumber(item.tx.errors.value ?? 0)} />
              </div>
            </section>

            <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} color="var(--chart-rx)" />
            <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} color="var(--chart-tx)" />

            <section className="metric-group">
              <h3>Packets / Drops / Errors</h3>
              <div className="chart-stack">
                <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={150} color="var(--chart-rx-packets)" />
                <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={150} color="var(--chart-tx-packets)" />
                <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={130} color="var(--chart-rx-dropped)" />
                <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={130} color="var(--chart-tx-dropped)" />
                <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={130} color="var(--chart-rx-errors)" />
                <MetricChart title="TX Errors" metric={metrics?.metrics["tx.errors"]} height={130} color="var(--chart-tx-errors)" />
              </div>
            </section>
          </>
        )}
      </div>
    </aside>
  );
}

function InterfaceOverview({ item, metrics }: { item: InterfaceListItem; metrics: InterfaceMetricsResponse | null }) {
  return (
    <div className="graph-mode-layout interface-overview-layout">
      <section className="graph-summary-band">
        <Stat label="RX" value={formatBitrate(item.rxBitrate.value ?? item.rxBitrate.avg)} />
        <Stat label="TX" value={formatBitrate(item.txBitrate.value ?? item.txBitrate.avg)} />
        <Stat label="Headroom" value={formatPercent(interfaceHeadroom(item))} />
        <Stat label="Link" value={formatLinkSummary(item)} />
        <Stat label="Drops" value={formatNumber((item.rx.dropped.value ?? 0) + (item.tx.dropped.value ?? 0))} />
        <Stat label="Errors" value={formatNumber((item.rx.errors.value ?? 0) + (item.tx.errors.value ?? 0))} />
      </section>
      <BandwidthUsagePanel item={item} compact />
      <section className="graph-card-grid interface-overview-grid">
        <MetricChart title="RX Utilization" metric={metrics?.metrics["rx.utilization"]} height={108} compact color="var(--chart-rx)" />
        <MetricChart title="TX Utilization" metric={metrics?.metrics["tx.utilization"]} height={108} compact color="var(--chart-tx)" />
        <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} height={126} compact color="var(--chart-rx)" />
        <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} height={126} compact color="var(--chart-tx)" />
        <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={108} compact color="var(--chart-rx-packets)" />
        <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={108} compact color="var(--chart-tx-packets)" />
        <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={108} compact color="var(--chart-rx-dropped)" />
        <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={108} compact color="var(--chart-tx-dropped)" />
        <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={108} compact color="var(--chart-rx-errors)" />
        <MetricChart title="TX Errors" metric={metrics?.metrics["tx.errors"]} height={108} compact color="var(--chart-tx-errors)" />
      </section>
    </div>
  );
}

function BandwidthUsagePanel({ item, compact = false }: { item: InterfaceListItem; compact?: boolean }) {
  const rxUsage = item.rxRate?.utilization;
  const txUsage = item.txRate?.utilization;
  const speed = item.link?.speedMbps ? formatLinkSpeed(item.link.speedMbps) : "unknown";
  return (
    <section className={`bandwidth-panel ${compact ? "compact" : ""}`}>
      <div className="bandwidth-panel-header">
        <h3>Link Capacity</h3>
        <span>{speed} / {item.link?.duplex ?? "duplex unknown"} / {item.link?.operstate ?? "state unknown"}</span>
      </div>
      <div className="bandwidth-gauge-grid">
        <BandwidthGauge label="RX" usage={rxUsage} bitrate={item.rxRate?.bitrateBps ?? item.rxBitrate.value ?? item.rxBitrate.avg} headroom={item.rxRate?.headroomBps} color="var(--chart-rx)" />
        <BandwidthGauge label="TX" usage={txUsage} bitrate={item.txRate?.bitrateBps ?? item.txBitrate.value ?? item.txBitrate.avg} headroom={item.txRate?.headroomBps} color="var(--chart-tx)" />
      </div>
    </section>
  );
}

function BandwidthGauge({ label, usage, bitrate, headroom, color }: { label: string; usage?: number; bitrate?: number; headroom?: number; color: string }) {
  const clamped = usage === undefined ? undefined : Math.max(0, Math.min(1, usage));
  const dash = clamped === undefined ? 0 : clamped * 100;
  const hasVisibleValue = clamped !== undefined && clamped >= 0.01;
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return <div className="stat-card"><span>{label}</span><strong>{value}</strong></div>;
}

function flowAccent(role: string) {
  return FLOW_ROLE_ACCENTS[role] ?? FLOW_ROLE_ACCENTS.default;
}

function colorForMetric(key: string) {
  const palette: Record<string, string> = {
    bitrate: "var(--chart-metric-bitrate)",
    packet_rate: "var(--chart-metric-packet-rate)",
    jitter: "var(--chart-metric-jitter)",
    rtt: "var(--chart-metric-rtt)",
    rttvar: "var(--chart-metric-rttvar)",
    bandwidth: "var(--chart-metric-bandwidth)",
    rate: "var(--chart-metric-rate)",
    rcvrate: "var(--chart-metric-rcvrate)",
    interval: "var(--chart-metric-interval)",
    clock_skew: "var(--chart-metric-clock-skew)",
    nak_seqno: "var(--chart-metric-nak-seqno)"
  };
  const root = key.split(".")[0];
  return palette[root] ?? fallbackMetricColor(root);
}

function fallbackMetricColor(key: string) {
  const colors = ["var(--chart-fallback-1)", "var(--chart-fallback-2)", "var(--chart-fallback-3)", "var(--chart-fallback-4)", "var(--chart-fallback-5)", "var(--chart-fallback-6)", "var(--chart-fallback-7)"];
  let hash = 0;
  for (const char of key) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return colors[hash % colors.length];
}

